Here is the commit message:
mtd: maps: sun_uflash: Declare uflash_devinit static

This fixes the following warning:
sun_uflash.c:50:5: error: no previous prototype for 'uflash_devinit'

Signed-off-by: Sam Ravnborg <sam@ravnborg.org>
Fixes: 0fcb70851fbf ("Makefile.extrawarn: turn on missing-prototypes globally")
Reviewed-by: Randy Dunlap <rdunlap@infradead.org>
Tested-by: Randy Dunlap <rdunlap@infradead.org> # build-tested
Cc: Andreas Larsson <andreas@gaisler.com>
Cc: "David S. Miller" <davem@davemloft.net>
Reviewed-by: Andreas Larsson <andreas@gaisler.com>
Acked-by: Miquel Raynal <miquel.raynal@bootlin.com>
Signed-off-by: Andreas Larsson <andreas@gaisler.com>
Link: https://lore.kernel.org/r/20240224-sam-fix-sparc32-all-builds-v2-3-1f186603c5c4@ravnborg.org

Here is the root cause:
The root cause of the bug is the lack of a previous prototype declaration for the function `uflash_devinit`, which leads to a warning when the `missing-prototypes` warning is enabled globally. This indicates that the function was being used without a proper declaration, which can lead to potential issues with function linkage and visibility in the codebase.

Here is the patch:

-int uflash_devinit(struct platform_device *op, struct device_node *dp)
+static int uflash_devinit(struct platform_device *op, struct device_node *dp)
 {
 	struct uflash_dev *up;

 	if (op->resource[1].flags) {
 		/* Non-CFI userflash device-- once I find one we
 		 * can work on supporting it.
 		 */
 		printk(KERN_ERR PFX "Unsupported device at %pOF, 0x%llx\n",
 		       dp, (unsigned long long)op->resource[0].start);

 		return -ENODEV;
 	}

 	up = kzalloc(sizeof(struct uflash_dev), GFP_KERNEL);
 	if (!up)
 		return -ENOMEM;

 	/* copy defaults and tweak parameters */
 	memcpy(&up->map, &uflash_map_templ, sizeof(uflash_map_templ));

 	up->map.size = resource_size(&op->resource[0]);

 	up->name = of_get_property(dp, "model", NULL);
 	if (up->name && 0 < strlen(up->name))
 		up->map.name = up->name;

 	up->map.phys = op->resource[0].start;

 	up->map.virt = of_ioremap(&op->resource[0], 0, up->map.size,
 				  DRIVER_NAME);
 	if (!up->map.virt) {
 		printk(KERN_ERR PFX "Failed to map device.\n");
 		kfree(up);

 		return -EINVAL;
 	}

 	simple_map_init(&up->map);

 	/* MTD registration */
 	up->mtd = do_map_probe("cfi_probe", &up->map);
 	if (!up->mtd) {
 		of_iounmap(&op->resource[0], up->map.virt, up->map.size);
 		kfree(up);

 		return -ENXIO;
 	}

 	up->mtd->owner = THIS_MODULE;

 	mtd_device_register(up->mtd, NULL, 0);

 	dev_set_drvdata(&op->dev, up);

 	return 0;
 }



